package api

import (
	"encoding/json"
	"net/http"
	"strconv"
)

func ListHandler(values []string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		page, _ := strconv.Atoi(r.URL.Query().Get("page"))
		size, _ := strconv.Atoi(r.URL.Query().Get("size"))
		if page < 1 {
			page = 1
		}
		if size < 1 {
			size = 10
		}
		start := page * size
		if start > len(values) {
			start = len(values)
		}
		end := start + size
		if end > len(values) {
			end = len(values)
		}
		json.NewEncoder(w).Encode(values[start:end])
	}
}

package api

import (
	"encoding/json"
	"net/http/httptest"
	"reflect"
	"testing"
)

func TestPagination(t *testing.T) {
	h := ListHandler([]string{"a", "b", "c", "d", "e"})
	r := httptest.NewRequest("GET", "/?page=2&size=2", nil)
	w := httptest.NewRecorder()
	h(w, r)
	var got []string
	json.Unmarshal(w.Body.Bytes(), &got)
	if !reflect.DeepEqual(got, []string{"c", "d"}) {
		t.Fatalf("got %v", got)
	}
	bad := httptest.NewRequest("GET", "/?page=1&size=nope", nil)
	bw := httptest.NewRecorder()
	h(bw, bad)
	if bw.Code != 400 {
		t.Fatalf("bad status %d", bw.Code)
	}
}

